local animationName_Pose2ToPose1 = "IdolLive3D_MainUI_Pose2ToPose1"
local animationName_Pose1ToPose2 = "IdolLive3D_MainUI_Pose1ToPose2"

local switchBtn_fadeInTime = 0.8
local switchBtn_fadeOutTime = 0.1


-- ========================================================



---@param uiMain_ table 
---@param switchBtnTF_ UnityEngine.Transform
function IdolLive3D_UISwitchBtn:__init( uiMain_, switchBtnTF_ )

    self.uiMain = uiMain_
    self.baseJson = self.uiMain.baseJson
    self.switch = switchBtnTF_
    self.uiKey = Live3D_UIKey.switchPanel

    -----
    local BtnSel1 = self.switch.transform:Find("Pose1/BtnSel")
    local BtnSel2 = self.switch.transform:Find("Pose2/BtnSel")
    assert( BtnSel1 and BtnSel2 )
    self._1_ImgBg  = BtnSel1:Find("ImgBg")
    self._1_ImgBg2 = BtnSel1:Find("ImgBg2")
    self._1_ImgIcon = BtnSel1:Find("ImgIcon")
    assert( self._1_ImgBg and self._1_ImgBg2 and self._1_ImgIcon  )
    self._2_ImgBg  = BtnSel2:Find("ImgBg")
    self._2_ImgBg2 = BtnSel2:Find("ImgBg2")
    self._2_ImgIcon = BtnSel2:Find("ImgIcon")
    assert( self._2_ImgBg and self._2_ImgBg2 and self._2_ImgIcon  )


    ------
    KTool.SetActive( self.switch.gameObject, true )
    CfUtils.SetCanvasGroupAlpha( self.switch.gameObject, 0.0 )
    CfUtils.SetCanvasGroupInteractable( self.switch.gameObject, false )


    self.smoothShow = IdolLive3D_UISmoothShowEnt.New( self.switch.gameObject, self.baseJson:IsIdleSwitchByButton(), false, false, 0.9, 3 )
    self.isActive = false   -- 是否点击可起效
    self.isIdle100To200 = true
    ---
    self.isCustomShow = true -- 定制脚本: isShow
    self.isCustomGray = false -- 定制脚本: isGray
    self.customClickFunc = nil -- 定制脚本: 按下按钮后的功能
    


    ------- 
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    self.events = CfUtils.EventsDecorated({
        -- 允许 客制代码 手动隐藏 本按钮:
        [IdolLive3D_States.EventSetUICustomShow] = function( uiKey_, isShow_, fadeTime_, isEffectImmediately_ )
            if uiKey_ ~= self.uiKey then 
                return
            end
            self.isCustomShow = (isShow_==true)
            if isEffectImmediately_ == true then 
                self:Show(true, fadeTime_)
            end
        end,

        -- 允许 客制代码 手动置灰 本按钮:
        [IdolLive3D_States.EventSetUICustomGray] = function( uiKey_, isGray_, isEffectImmediately_ )
            if uiKey_ ~= self.uiKey then 
                return
            end
            self.isCustomGray = (isGray_==true)
            if isEffectImmediately_ == true then 
                self:SetGray(true)
            end
        end,

        -- 外部指定按钮功能, 可写入 nil 来释放;
        [IdolLive3D_States.EventSetUIBtnCustomClickFunc] = function( uiKey_, clickFunc_ )
            if uiKey_ ~= self.uiKey then 
                return
            end
            self.customClickFunc = clickFunc_
        end,
    })

    --------
    if self.baseJson:IsIdleSwitchByButton() then 
        SetButtonAction(self.switch, function()
            if self.isActive == true then 
                if isNotNull(self.customClickFunc) and type(self.customClickFunc) == "function" then
                    -- 客制按钮功能:
                    self.customClickFunc(self)
                else
                    -- 默认按钮功能:
                    self:OnClick()
                end
            end 
        end)
    else
        self.isActive = false
        self:Show( false )
    end 
    
end




-- 需手动调用 Delete()
function IdolLive3D_UISwitchBtn:__delete()
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
end



function IdolLive3D_UISwitchBtn:SelfUpdate()
    self.smoothShow:SelfUpdate()
end

----------------------------------------------------------


function IdolLive3D_UISwitchBtn:SetActive( isActive_ )
    self.isActive = (isActive_==true)
end


---@param isShow_ boolean 
---@param fadeInTime_ number | nil
function IdolLive3D_UISwitchBtn:Show( isShow_, fadeTime_ )
    --printError(" show-1-:" .. tostring(isShow_) .. ", -2-:" .. tostring(self.isCustomShow) .. ", time = " .. tostring(fadeInTime_))
    local doShow = (isShow_==true and self.isCustomShow==true)
    if isNull(fadeTime_) then 
        fadeTime_ = doShow and switchBtn_fadeInTime or switchBtn_fadeOutTime
    end 
    self.smoothShow:SetShowOrHide( isShow_==true and self.isCustomShow==true, fadeTime_ )
end



---@param isGray_ boolean @ 允许重复设置
function IdolLive3D_UISwitchBtn:SetGray( isGray_ )
    local doGray = (isGray_ == true or self.isCustomGray == true )
    ---- 
    KTool.SetActive( self._1_ImgBg.gameObject, not doGray )
    KTool.SetActive( self._1_ImgBg2.gameObject, doGray )
    CfUtils.SetUISwitchImage( self._1_ImgIcon.gameObject, doGray and 2 or 1 )

    KTool.SetActive( self._2_ImgBg.gameObject, not doGray )
    KTool.SetActive( self._2_ImgBg2.gameObject, doGray )
    CfUtils.SetUISwitchImage( self._2_ImgIcon.gameObject, doGray and 2 or 1 )
end



-- 默认的按下按钮后的功能:
function IdolLive3D_UISwitchBtn:OnClick()
    Events.Broadcast(IdolLive3D_States.EventSwitchIdleToOth, nil) -- !! V1 专用, 未来实现新型逻辑来替代
    ---
    CfUtils.PlayAnimation( self.switch.gameObject, self.isIdle100To200==true and animationName_Pose2ToPose1 or animationName_Pose1ToPose2 )
    self.isIdle100To200 = not self.isIdle100To200
end




return IdolLive3D_UISwitchBtn
